// Rust + C++ polyglot: prints the kth Fibonacci number (f(0)=1, f(1)=1)
// from the command line argument.
//
// The line below is a no-op comment in C++ (a preprocessor directive
// starting with #), and a Rust attribute that enables the C-style
// `//` preprocessor syntax. The `#if 1 ... #else ... #endif` block is
// then seen as C++ code by g++ and as a Rust raw string literal by rustc.
#![feature(c_str_literals)]
#if 1
#include <cstdio>
#include <cstdlib>
int main(int argc, char** argv) {
    long n = 0;
    if (argc > 1) n = atol(argv[1]);
    long a = 1, b = 1, c;
    for (long i = 0; i < n; i++) { c = a + b; a = b; b = c; }
    printf("%ld\n", a);
    return 0;
}
#else
fn main() {
    let mut args = std::env::args().skip(1);
    let n: u64 = args.next().and_then(|s| s.parse().ok()).unwrap_or(0);
    let mut a: u64 = 1;
    let mut b: u64 = 1;
    for _ in 0..n {
        let c = a.wrapping_add(b);
        a = b;
        b = c;
    }
    println!("{}", a);
}
#endif
EOF
